RARE_BOPOMOFO = "ㄍㄠ ㄘㄠˇ ㄎㄢ"


class WindowsLikeConsole:
    """A stdout that rejects non-ASCII, like the Windows console codecs."""

    def __init__(self):
        self.chunks = []

    def write(self, text):
        text.encode("ascii")  # UnicodeEncodeError, like cp950/cp1252 consoles
        self.chunks.append(text)
        return len(text)

    def flush(self):
        pass

    def getvalue(self):
        return "".join(self.chunks)


