    def userphrase_get(self, phrase_buf, phrase_len, bopomofo_buf, bopomofo_len):
        phrase, bopomofo = self._pending.pop(0)
        phrase_buf.value = phrase.encode("utf-8")
        bopomofo_buf.value = bopomofo.encode("utf-8")
