class UserPhraseDeleteLoopTests(unittest.TestCase):

    @classmethod
    def setUpClass(cls):
        try:
            import tornado.web  # noqa: F401
        except ImportError:
            raise unittest.SkipTest("tornado not installed for this interpreter")
        cls.config_tool = _load_config_tool()

    def setUp(self):
        self._saved_ctx = self.config_tool.chewing_ctx
        self.use_stub()
        self.console = WindowsLikeConsole()
        self._stdout = contextlib.ExitStack()
        self.addCleanup(self._stdout.close)
        self._stdout.enter_context(mock.patch.object(sys, "stdout", self.console))

    def tearDown(self):
        self.config_tool.chewing_ctx = self._saved_ctx

    def use_stub(self, **kwargs):
        self.stub = StubChewingContext(**kwargs)
        self.config_tool.chewing_ctx = self.stub

    def post(self, body):
        handler = FakeHandler(body)
        self.config_tool.UserPhraseHandler.post(handler)
        return handler.written

    def get(self):
        handler = FakeHandler({})
        self.config_tool.UserPhraseHandler.get(handler)
        return handler.written

    def test_rare_char_add_and_remove_reach_libchewing_and_report_success(self):
        written = self.post({
            "add": [{"phrase": RARE_PHRASE, "bopomofo": RARE_BOPOMOFO}],
            "remove": [{"phrase": RARE_PHRASE, "bopomofo": RARE_BOPOMOFO}],
        })

        self.assertEqual(self.stub.added,
                         [(RARE_PHRASE.encode("utf-8"), RARE_BOPOMOFO.encode("utf-8"))])
        self.assertEqual(self.stub.removed,
                         [(RARE_PHRASE.encode("utf-8"), RARE_BOPOMOFO.encode("utf-8"))])
        self.assertEqual(written, {"result": 1})

    def test_enumerating_rare_char_phrases_reports_data_and_prints_nothing(self):
        self.use_stub(phrases=[(RARE_PHRASE, RARE_BOPOMOFO), ("栞", "ㄎㄢ")])

        written = self.get()

        self.assertEqual(written, {"data": [
            {"phrase": RARE_PHRASE, "bopomofo": RARE_BOPOMOFO},
            {"phrase": "栞", "bopomofo": "ㄎㄢ"},
        ]})
        self.assertEqual(self.console.getvalue(), "")

    def test_failed_removal_is_reported_even_when_a_later_one_succeeds(self):
        # libchewing's userphrase_remove returns rows deleted: 0 means the
        # phrase was not found, 1 means it was removed.
        self.use_stub(remove_returns=[0, 1])

        written = self.post({"remove": [
            {"phrase": "_missing", "bopomofo": "ㄇㄧˊ"},
            {"phrase": RARE_PHRASE, "bopomofo": RARE_BOPOMOFO},
        ]})

        self.assertEqual(written, {"result": 0})

    def test_remove_error_return_is_reported_as_failure(self):
        # A negative return (invalid arguments) must not read as success.
        self.use_stub(remove_returns=[-1])

        written = self.post({"remove": [
            {"phrase": RARE_PHRASE, "bopomofo": RARE_BOPOMOFO},
        ]})

        self.assertEqual(written, {"result": 0})

    def test_failed_add_is_reported_even_when_removals_succeed(self):
        self.use_stub(add_returns=[0])

        written = self.post({
            "add": [{"phrase": RARE_PHRASE, "bopomofo": "ㄍㄠ"}],
            "remove": [{"phrase": RARE_PHRASE, "bopomofo": RARE_BOPOMOFO}],
        })

        self.assertEqual(written, {"result": 0})


